	for _, p := range w {
		if p.Type == WPPlugin {
			ps = append(ps, p)
		}
	}
	return
}

// Themes returns a slice of themes of the installed WordPress
func (w WordPressPackages) Themes() (ps []WpPackage) {
	for _, p := range w {
		if p.Type == WPTheme {
			ps = append(ps, p)
		}
	}
	return
}

// Find searches by specified name
